import fs from 'node:fs';
import path from 'node:path';
import { GUIDES } from '../db/guides/content.mjs';

function sqlString(value) {
  return `'${String(value).replaceAll("'", "''")}'`;
}

function jsonb(value) {
  return `$$${JSON.stringify(value)}$$::jsonb`;
}

const lines = [
  '-- Generated by scripts/gen-travel-guides-seed.mjs from db/guides/content.mjs',
  '-- Travelar-authored editorial. Re-run the generator after editing content.mjs.',
  '',
];

for (const guide of GUIDES) {
  lines.push(`insert into app.travel_guide (
  id, slug, topic, related_mode, cover_path, status, sort_order, published_at, researched_at, source_notes, source
) values (
  '${guide.id}',
  ${sqlString(guide.slug)},
  ${sqlString(guide.topic)},
  ${sqlString(guide.related_mode)},
  ${sqlString(guide.cover_path)},
  'published',
  ${guide.sort_order},
  timestamptz '2026-11-08 00:00:00+00',
  date ${sqlString(guide.researched_at)},
  ${sqlString(guide.source_notes)},
  'reference'
)
on conflict (slug) do update set
  topic = excluded.topic,
  related_mode = excluded.related_mode,
  cover_path = excluded.cover_path,
  status = excluded.status,
  sort_order = excluded.sort_order,
  published_at = excluded.published_at,
  researched_at = excluded.researched_at,
  source_notes = excluded.source_notes,
  updated_at = now();
`);

  for (const [locale, copy] of Object.entries(guide.locales)) {
    lines.push(`insert into app.travel_guide_locale (guide_id, locale, title, excerpt, cover_alt, sections)
values (
  '${guide.id}',
  ${sqlString(locale)},
  ${sqlString(copy.title)},
  ${sqlString(copy.excerpt)},
  ${sqlString(copy.cover_alt)},
  ${jsonb(copy.sections)}
)
on conflict (guide_id, locale) do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  cover_alt = excluded.cover_alt,
  sections = excluded.sections;
`);
  }
}

const out = path.join(process.cwd(), 'db', 'seed', '0005_travel_guides.sql');
fs.writeFileSync(out, `${lines.join('\n')}\n`);
console.log(JSON.stringify({ ok: true, file: 'db/seed/0005_travel_guides.sql', guides: GUIDES.length }));
